void poly_shift(poly *r, int32_t shift) {
  poly_shift_avx(r, shift);
}

void ring_shift(ring_element *r, int32_t shift) {
  for(unsigned int i = 0; i < RRLWR_K; i++) {
    poly_shift(&r->x[i], shift);
  }
}

void ring_shift_and_sub(ring_element *r, const ring_element *f, const ring_element *g, int32_t shift) {
  for(unsigned int i = 0; i < RRLWR_K; i++) {
    for(unsigned int j = 0; j < RRLWR_N; j++) {
      r->x[i].coeffs[j] = f->x[i].coeffs[j] - (g->x[i].coeffs[j] << shift);
    }
  }
}

// Finds two unique elements r0, r1 such that 
// * r0 in [-2^(d/2), 2^(d/2)-1]
// * r1 in [-2^(d-len)/2, 2^(d-len)/2-1]
// * r = r0 + 2^d*r1 mod 2^len
// Note that it could be false that r = r0 + 2^d*r1 as integers as there could be carries
static inline void power2round(int32_t *r0, int32_t *r1, int32_t r, int32_t d) {
  int32_t powd2 = (int32_t)1 << (d-1); // 2^(d/2)
  *r0 = ((r+powd2) & ((powd2<<1)-1)) - powd2; // Signed representative in [-2^(d/2), 2^(d/2)-1]
  *r1 = ((r - *r0) >> d);
}

void poly_power2round(poly *r0, poly *r1, const poly *f, int32_t d) {
  poly_power2round_avx(r0, r1, f, d);
}

void ring_power2round_and_pack(unsigned char *r0, unsigned char *r1, const ring_element *f) {
  poly f0, f1;

  for(unsigned int i = 0; i < RRLWR_K; i++) {
    poly_power2round(&f0, &f1, &f->x[i], RRLWR_SIGN_D);
    poly_pack(r0 + i*RRLWR_SIGN_PACKED_POLYB0_LEN, &f0, RRLWR_SIGN_D);
    poly_pack(r1 + i*RRLWR_SIGN_PACKED_POLYB1_LEN, &f1, RRLWR_SIGN_LOGP-RRLWR_SIGN_D);
  }
}

void ring_w1(unsigned char w1[RRLWR_SIGN_PACKED_W1_LEN], const ring_element *w) {
  poly w1poly;
  int32_t w0;

  for(unsigned int i = 0; i < RRLWR_K; i++) {
    for(unsigned int j = 0; j < RRLWR_N; j++) {
      power2round(&w0, &w1poly.coeffs[j], w->x[i].coeffs[j], RRLWR_SIGN_LOG_GAMMA2+1);
    }
    poly_pack(w1+i*RRLWR_SIGN_PACKED_POLYW1_LEN, &w1poly, RRLWR_SIGN_LOGQ-(RRLWR_SIGN_LOG_GAMMA2+1));
  }
}

// Unpack a byte sequence into 10-bit coefficient indices
static void sample_challenge_10b(unsigned int out[RRLWR_SIGN_SAMPLE_C_NUM_INDICES], unsigned char in[RRLWR_SIGN_SAMPLE_C_LEN]) {
  unsigned char *inp = in;
  unsigned int *outp = out;
  for(unsigned int i = 0; i < RRLWR_SIGN_SAMPLE_C_LEN; i += 5) {
    outp[0] =   inp[0]               | ((inp[1] & 0x03) << 8); // (8, 2)
    outp[1] = ((inp[1] >> 2) & 0x3F) | ((inp[2] & 0x0F) << 6); // (6, 4)
    outp[2] = ((inp[2] >> 4) & 0x0F) | ((inp[3] & 0x3F) << 4); // (4, 6)
    outp[3] = ((inp[3] >> 6) & 0x03) | ( inp[4]         << 2); // (2, 8)
    inp += 5;
    outp += 4;
  }
}

int poly_sampleInBall(poly *c, unsigned char ctilde[RRLWR_SIGN_CTILDE_LEN]) {

  unsigned int i, pos, signs_pos, b;
  int32_t sign;
  unsigned char hash_out_buffer[RRLWR_SIGN_SAMPLE_C_LEN]; // Buffer for sampled bytes
  unsigned int poly_indices[RRLWR_SIGN_SAMPLE_C_NUM_INDICES]; // Buffer for 10-bit indices
  unsigned int hash_counter;
  unsigned char signs_buffer[RRLWR_SIGN_MAX_TAU_BYTES];

  // Sample the signs
  RRLWR_SIGN_HASH_SAMPLE_C_DOMAIN(signs_buffer, RRLWR_SIGN_MAX_TAU_BYTES, ctilde, 0, 0);
  signs_pos = 0;

  // Sample the initial output buffer
  hash_counter = 0;
  RRLWR_SIGN_HASH_SAMPLE_C_DOMAIN(hash_out_buffer, RRLWR_SIGN_SAMPLE_C_LEN, ctilde, 1, hash_counter);
  sample_challenge_10b(poly_indices, hash_out_buffer);
  pos = 0;

  // Initialize c to 0
  for(i = 0; i < RRLWR_N; i++) {
    c->coeffs[i] = 0;
  }

  for(i = RRLWR_N-RRLWR_SIGN_TAU; i < RRLWR_N; i++) {

    // Sample an index <= i
    do {
      if(pos >= RRLWR_SIGN_SAMPLE_C_NUM_INDICES) {

        if(hash_counter == 255) {
          return -1; // Failed as 256 hash outputs have been exhausted
        }

        hash_counter++;
        RRLWR_SIGN_HASH_SAMPLE_C_DOMAIN(hash_out_buffer, RRLWR_SIGN_SAMPLE_C_LEN, ctilde, 1, hash_counter);
        sample_challenge_10b(poly_indices, hash_out_buffer);
        pos = 0;
      }

      b = poly_indices[pos++];
    } while(b > i);

    c->coeffs[i] = c->coeffs[b];
    sign = (int32_t)((signs_buffer[signs_pos >> 3] >> (signs_pos & 0x7)) & 1); // Take sign from buffer
    signs_pos++;
    c->coeffs[b] = 1 - 2*sign;
  }

  return 0;
}

int poly_check_norm(const poly *f, int32_t bound) {
  unsigned int i;
  int32_t t;

  for(i = 0; i < RRLWR_N; i++) {
    t = f->coeffs[i] >> 31; // Sign mask
    t = f->coeffs[i] - (t & 2*f->coeffs[i]);

    if(t >= bound) {
      return -1;
    }
  }

  return 0;
}

int poly_make_hint(poly *h, const poly *f, const poly *g) {
  int32_t f0, f1, g0, g1;
  int hint_weight = 0;

  // Compare high bits and set hint to 1 if they are different
  for(unsigned int i = 0; i < RRLWR_N; i++) {
    power2round(&f0, &f1, f->coeffs[i], RRLWR_SIGN_LOG_GAMMA2+1);
    power2round(&g0, &g1, g->coeffs[i], RRLWR_SIGN_LOG_GAMMA2+1);
    if(f1 != g1) {
      h->coeffs[i] = 1;
      hint_weight++;
    }
    else {
      h->coeffs[i] = 0;
    }
  }

  return hint_weight;
}

void poly_apply_hint(poly *r, const poly *f, const poly *h) {
  poly_apply_hint_avx(r, f, h);
}

void ring_pack_hint(unsigned char hb[RRLWR_SIGN_H_LEN8], const ring_element *hint) {
  unsigned int i, j, k = 0;
  uint16_t h[RRLWR_SIGN_H_LEN16] = {0};

  for(i = 0; i < RRLWR_SIGN_H_LEN16; i++) {
    h[i] = 0;
  }

  for(i = 0; i < RRLWR_K; i++) {
    for(j = 0; j < RRLWR_N; j++) {
      if(hint->x[i].coeffs[j] != 0) {
        h[k++] = j;
      }
    }

    h[RRLWR_SIGN_OMEGA + i] = k;
  }

  // Convert to a byte array
  for(i = 0; i < (RRLWR_SIGN_OMEGA+RRLWR_K)/4; i++) {
    hb[5*i+0] =   h[4*i+0]       & 0xFF;                             // 0, - --> (8, -)
    hb[5*i+1] = ((h[4*i+0] >> 8) & 0x03) | ((h[4*i+1] & 0x3F) << 2); // 0, 1 --> (2, 6)
    hb[5*i+2] = ((h[4*i+1] >> 6) & 0x0F) | ((h[4*i+2] & 0x0F) << 4); // 1, 2 --> (4, 4)
    hb[5*i+3] = ((h[4*i+2] >> 4) & 0x3F) | ((h[4*i+3] & 0x03) << 6); // 2, 3 --> (6, 2)
    hb[5*i+4] = ((h[4*i+3] >> 2) & 0xFF);                            // 3, - --> (8, -)
  }
}

int ring_unpack_hint(ring_element *hint, const unsigned char hb[RRLWR_SIGN_H_LEN8]) {
  unsigned int i, j, k = 0;
  uint16_t h[RRLWR_SIGN_H_LEN16];

  for(i = 0; i < RRLWR_SIGN_H_LEN16; i++) {
    h[i] = 0;
  }

  // Convert from a byte array
  for(i = 0; i < (RRLWR_SIGN_OMEGA+RRLWR_K)/4; i++) {
    h[4*i+0] =   (int16_t)hb[5*i+0]               | (((int16_t)hb[5*i+1] & 0x03) << 8); // 0, 1 --> (8, 2)
    h[4*i+1] = (((int16_t)hb[5*i+1] >> 2) & 0x3F) | (((int16_t)hb[5*i+2] & 0x0F) << 6); // 1, 2 --> (6, 4)
    h[4*i+2] = (((int16_t)hb[5*i+2] >> 4) & 0x0F) | (((int16_t)hb[5*i+3] & 0x3F) << 4); // 2, 3 --> (4, 6)
    h[4*i+3] = (((int16_t)hb[5*i+3] >> 6) & 0x03) | (((int16_t)hb[5*i+4] & 0xFF) << 2); // 3, 4 --> (2, 8)
  }

  for(i = 0; i < RRLWR_K; i++) {
    for(j = 0; j < RRLWR_N; j++) {
      hint->x[i].coeffs[j] = 0;
    }

    if(h[RRLWR_SIGN_OMEGA + i] < k || h[RRLWR_SIGN_OMEGA + i] > RRLWR_SIGN_OMEGA) {
      return -1;
    }

    for(j = k; j < h[RRLWR_SIGN_OMEGA + i]; j++) {
      if(j > k && h[j] <= h[j-1]) {
        return -1;
      }
      hint->x[i].coeffs[h[j]] = 1;
    }

    k = h[RRLWR_SIGN_OMEGA + i];
  }

  /* Extra indices are zero for strong unforgeability */
  for(j = k; j < RRLWR_SIGN_OMEGA; j++) {
    if(h[j]) {
      return -1;
    }
  }

  return 0;
}
